#!/usr/bin/env python3
# Writes lib/pydoc_data/ (round 87) from the running Python's own
# pydoc_data: topics.ny holds the `topics` dictionary pydoc's Helper reads
# (the Language Reference's sections as text, generated by Sphinx when
# CPython is released), _pydoc.css the style sheet next to it.
#
#     python3 tools/gen_pydoc_topics.py            # from the host's python3
#     python3.12 tools/gen_pydoc_topics.py         # another version's text
#
# Each topic is written as one string literal (repr), not as Sphinx's
# implicit concatenation of short pieces: the same dictionary, a quarter of
# the tokens to parse.
import os
import sys

import pydoc_data
import pydoc_data.topics

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
OUT = os.path.join(ROOT, "lib", "pydoc_data")


def main():
    os.makedirs(OUT, exist_ok=True)
    ver = "%d.%d.%d" % sys.version_info[:3]
    with open(os.path.join(OUT, "__init__.ny"), "w", encoding="utf-8") as f:
        f.write("# nython: module    (a package: pydoc_data.topics)\n")
        f.write("# nython: python    (Python's binding rule: a name a function binds is its local - round 85)\n")
        f.write("# lib/pydoc_data - Python's pydoc_data package (round 87): topics.ny, the\n")
        f.write("# Language Reference's sections pydoc's help() shows (generated by\n")
        f.write("# tools/gen_pydoc_topics.py from CPython " + ver + "'s), and _pydoc.css.\n")
    topics = pydoc_data.topics.topics
    with open(os.path.join(OUT, "topics.ny"), "w", encoding="utf-8") as f:
        f.write("# nython: module    (import it by name: it runs in a module scope of its own)\n")
        f.write("# nython: python    (Python's binding rule: a name a function binds is its local - round 85)\n")
        f.write("# lib/pydoc_data/topics.ny - GENERATED by tools/gen_pydoc_topics.py from\n")
        f.write("# CPython " + ver + "'s pydoc_data.topics (round 87): the text of every topic\n")
        f.write("# and keyword pydoc's help() knows (" + str(len(topics)) + " entries). Do not edit.\n")
        f.write("topics = {\n")
        for k in sorted(topics):
            f.write("    " + repr(k) + ": " + repr(topics[k]) + ",\n")
        f.write("}\n")
    css = os.path.join(os.path.dirname(pydoc_data.__file__), "_pydoc.css")
    if os.path.exists(css):
        with open(css, encoding="utf-8") as src, open(os.path.join(OUT, "_pydoc.css"), "w", encoding="utf-8") as dst:
            dst.write(src.read())
    print("wrote", OUT, "(" + str(len(topics)) + " topics from Python " + ver + ")")


if __name__ == "__main__":
    main()
